package dev.gbppimentel.snapcompanion;
import java.nio.*;
import java.util.*;
import org.junit.*;
import static org.junit.Assert.*;
public class EdenResearchTest {
    @Test public void courseIdentityAndDisabledLevelSentinelsAreKeptSeparate()throws Exception{
        byte[] records=new byte[15464],flags=new byte[2960];ByteBuffer b=ByteBuffer.wrap(records).order(ByteOrder.LITTLE_ENDIAN);flags[0]=2;b.putInt(0,2);b.putShort(8,(short)1);b.putShort(12,(short)40000);b.putShort(14,(short)35266);
        List<EdenResearch.Course> courses=EdenResearch.decode(records,flags,GuideBookTest.asset("guidebook.json"));var park=courses.stream().filter(c->c.id().equals("park-day")).findFirst().orElseThrow();assertEquals(75266,park.points());assertEquals("Lv. 2",park.level());assertEquals(2,park.plays());assertEquals("Lv. 1",courses.stream().filter(c->c.id().equals("path-day")).findFirst().orElseThrow().level());
    }
    @Test public void inconsistentCourseFlagsAndMalformedResearchAreRejected()throws Exception{
        String guide=GuideBookTest.asset("guidebook.json");byte[] records=new byte[15464],flags=new byte[2960];ByteBuffer b=ByteBuffer.wrap(records).order(ByteOrder.LITTLE_ENDIAN);b.putInt(0,1);assertThrows(java.io.IOException.class,()->EdenResearch.decode(records,flags,guide));flags[0]=2;b.putShort(20,(short)1);assertThrows(java.io.IOException.class,()->EdenResearch.decode(records,flags,guide));assertThrows(java.io.IOException.class,()->EdenResearch.decode(new byte[100],flags,guide));
    }
    @Test public void separateColorEntriesMayShareOneSpeciesId()throws Exception{byte[] records=new byte[15464],flags=new byte[2960];flags[0]=2;ByteBuffer b=ByteBuffer.wrap(records).order(ByteOrder.LITTLE_ENDIAN);b.putInt(0,3);b.putShort(8,(short)61);b.putShort(12,(short)4200);b.putShort(20,(short)61);b.putShort(22,(short)2);b.putShort(24,(short)4300);var park=EdenResearch.decode(records,flags,GuideBookTest.asset("guidebook.json")).stream().filter(c->c.id().equals("park-day")).findFirst().orElseThrow();assertEquals(8500,park.points());assertEquals(2,park.subjects());b.putShort(22,(short)0);assertThrows(java.io.IOException.class,()->EdenResearch.decode(records,flags,GuideBookTest.asset("guidebook.json")));}
    @Test public void pointOffsetMatchesTheOwnedGetterIncludingClampAndMaximum()throws Exception{String guide=GuideBookTest.asset("guidebook.json");byte[] records=new byte[15464],flags=new byte[2960];flags[0]=2;ByteBuffer b=ByteBuffer.wrap(records).order(ByteOrder.LITTLE_ENDIAN);b.putShort(8,(short)1);b.putShort(12,(short)60000);b.putShort(14,(short)60000);b.putShort(16,(short)60000);b.putShort(18,(short)60000);int offset=50000;for(int k=0;k<3;k++)records[497+k]=(byte)(offset>>(8*k));var park=EdenResearch.decode(records,flags,guide).get(0);assertEquals(240000,park.grossPoints());assertEquals(50000,park.pointOffset());assertEquals(190000,park.points());assertEquals("Lv. 3",park.level());Arrays.fill(records,497,500,(byte)0xff);assertEquals(0,EdenResearch.decode(records,flags,guide).get(0).points());}
    @Test public void courseDiscoveryBitsAreIndependentOfResearchSubjectsAndPhotoScores()throws Exception{byte[] records=new byte[15464],flags=new byte[2960];ByteBuffer.wrap(records).order(ByteOrder.LITTLE_ENDIAN).putShort(9*504+488,(short)((1<<3)|(1<<6)));var forest=EdenResearch.decode(records,flags,GuideBookTest.asset("guidebook.json")).stream().filter(c->c.id().equals("forest")).findFirst().orElseThrow();assertEquals(72,forest.discoveryMask());assertEquals(0,forest.subjects());assertEquals(0,forest.points());}
}
